{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Molecule 1 (omadacycline) showed an absolute oral bioavailability of 34.5% in healthy adults, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Molecule 3 (5-hydroxyrofecoxib) had an oral bioavailability of 0.140 (14%) after a 25 mg oral dose versus i.v. in healthy subjects, arguing for F < 20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C19"],
      "claim": "Molecule 5 (epicillin) had an oral bioavailability of 3.9% in patients with cystic fibrosis, but this disease-state measurement is less transferable to ordinary conditions.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The highest-transferability direct absolute F record is 34.5% in healthy adults, supporting high. The main contradictory numeric record is 14% in healthy subjects, with additional low-F records being disease-state, indirect, or qualitative. On balance, high is better supported, but with moderate confidence due to conflicting low evidence.",
  "evidence_gaps": [
    "Only one high-quality direct absolute F measurement in healthy adults supports high; the other direct numeric F is below threshold.",
    "Several low-F records are qualitative, indirect, or from disease-state conditions, so their threshold relevance is uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

